INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('b2f6cbee-5d5a-5145-87b4-8e2936426456', '28997544-0d87-4b05-9ee2-7c474513c108', 'b6e0f952-8796-57b0-a451-157375298e36', NULL, NULL, 'Every subject a space draws on gives the same share of its own hours (a share between 10 and 30 percent).', 'placeholder', 'low', 'No source.', 'The share is unknown. The same range is used for all four spaces. With real hours the absolute time a space takes differs by subject, because the subjects have different hours.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('4b9aed9c-2af2-5625-a708-9a6d228fcf07', '28997544-0d87-4b05-9ee2-7c474513c108', 'b6e0f952-8796-57b0-a451-157375298e36', NULL, NULL, 'Grades 1 to 4 are taught inside Sachunterricht for every space, including the three disciplinary spaces.', 'literature', 'high', 'VwV Stundentafeln, Anlage 1a (read directly 2026-10-25).', 'The Grundschule has no lessons of biology, social studies or computing of its own. Sachunterricht is one integrated subject.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('cff49d3e-d28a-565a-8e6d-55216c053acb', '28997544-0d87-4b05-9ee2-7c474513c108', 'b6e0f952-8796-57b0-a451-157375298e36', NULL, NULL, 'In the grade band 3-5, two thirds of a stage sits in Sachunterricht (grades 3 and 4) and one third in the subject of grade 5.', 'derived', 'medium', 'Counted from the grade bands of the axis.', 'The band holds three school years. A stage cannot be placed in one year, so the split follows the years.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('79e65153-5b48-5dea-97bf-92b858d0f5ac', '28997544-0d87-4b05-9ee2-7c474513c108', 'b6e0f952-8796-57b0-a451-157375298e36', NULL, NULL, 'Grades 11 and 12 (Kursstufe) are not modelled in this version.', 'derived', 'high', 'VwV Stundentafeln has no table for the Kursstufe. Rules are in SOGYA, transcribed by an agent and not re-read.', 'Courses are chosen individually and the Grundkurs and Leistungskurs hours differ. The stages of the 9-12 band are placed in grades 9 and 10 only, so they carry less time than their band would suggest.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('57556e9a-f438-5bf6-ba2c-21c42984e34f', '28997544-0d87-4b05-9ee2-7c474513c108', '49134ad6-939d-57e3-abca-00bc79db722d', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the space''s time as a thread.', 'placeholder', 'low', 'No source.', 'That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('8a916411-b56b-58fd-962c-9d24cabf5ca0', '28997544-0d87-4b05-9ee2-7c474513c108', '554992ce-e3c5-528d-ba2f-81880ce0ff97', NULL, NULL, 'Inside a band, each stage takes its own stretch of the band''s teaching time, in dependency order.', 'derived', 'low', 'Design note 2026-10-25, section 5.11.', 'The links come from this space''s own prerequisite claims. This is a rule of the model and makes no claim about how any school should sequence.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('86ae373c-2c5c-58d0-8b2f-3bfe37710e03', '28997544-0d87-4b05-9ee2-7c474513c108', '1ef3326a-3465-5070-9f22-716ac803c5fb', NULL, NULL, 'This plan reverses the dependency order on purpose. It is a negative control for the order check and carries no design intent.', 'derived', 'high', 'Design note 2026-10-25, section 5.11.', 'A check that never reports a violation tells us little.', NULL) ON CONFLICT (id) DO NOTHING;

-- interdisciplinary-lpm-synth: 16 stages, 28 ordering claims, home subject biology
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, jurisdiction, source, status, subject)
VALUES ('41496b4b-11f1-5341-a51e-6912e729bbd7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'Sachunterricht: Sachsen Grundschule 2026/27', 'Sachunterricht lesson hours of the Sachsen school year 2026/27, one unit per year from kindergarten (year 1) to grade 12 (year 13). Years outside the school type of this subject have no hours. Available time is a range from 25 weeks to 39 weeks.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"kindergarten","label":"Kindergarten","where":{"year":{"eq":1,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-1","label":"Grade 1","where":{"year":{"eq":2,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-2","label":"Grade 2","where":{"year":{"eq":3,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-3","label":"Grade 3","where":{"year":{"eq":4,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-4","label":"Grade 4","where":{"year":{"eq":5,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-5","label":"Grade 5","where":{"year":{"eq":6,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-6","label":"Grade 6","where":{"year":{"eq":7,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-7","label":"Grade 7","where":{"year":{"eq":8,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-8","label":"Grade 8","where":{"year":{"eq":9,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-9","label":"Grade 9","where":{"year":{"eq":10,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-10","label":"Grade 10","where":{"year":{"eq":11,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-11","label":"Grade 11","where":{"year":{"eq":12,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-12","label":"Grade 12","where":{"year":{"eq":13,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}}]}'::jsonb, 'DE-SN', 'VwV Stundentafeln vom 20.6.2018 (MBl. SMK S. 347), Fassung gueltig 2026-08-01 bis 2027-07-31, https://www.revosax.sachsen.de/vorschrift/17744.7. Weekly hours read directly from the official PDF on 2026-10-25.', 'proposed', 'sachunterricht') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('772cae11-20d6-5cc1-9107-629d0dd3d837', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, '41496b4b-11f1-5341-a51e-6912e729bbd7', NULL, 'Sachunterricht has 3 weekly lesson hours in each of grades 1 to 4 (Grundschule, Anlage 1a). It is one integrated subject. Biologie, Chemie, Physik, Informatik, Geschichte, Geographie and Gemeinschaftskunde have no lessons of their own in grades 1 to 4.', 'literature', 'high', 'VwV Stundentafeln, Anlage 1a (https://revosax.sachsen.de/attachments/38081), read directly from the PDF 2026-10-25.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
