VALUES ('a644fe2b-4e17-5395-b824-afd94651e5b3', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, '738918e3-b368-59c7-a522-55a803fbd042', NULL, 'The social group adds Gemeinschaftskunde/Rechtserziehung/Wirtschaft, Geschichte, Geographie and Ethik: 5, 6, 7, 6, 7 and 8 weekly lesson hours in grades 5 to 10 (Anlage 4a). Students take Ethik or Religion, and the model counts that slot as Ethik. Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25. The grouping of four subjects into one host is a modelling choice.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, jurisdiction, source, status, subject)
VALUES ('b83f2e8b-a036-517f-934e-2ac89f1872d9', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'Computing: Sachsen Gymnasium 2026/27', 'Computer science lesson hours of the Sachsen school year 2026/27, one unit per year from kindergarten (year 1) to grade 12 (year 13). Years outside the school type of this subject have no hours. Available time is a range from 25 weeks to 39 weeks.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"kindergarten","label":"Kindergarten","where":{"year":{"eq":1,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-1","label":"Grade 1","where":{"year":{"eq":2,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-2","label":"Grade 2","where":{"year":{"eq":3,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-3","label":"Grade 3","where":{"year":{"eq":4,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-4","label":"Grade 4","where":{"year":{"eq":5,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-5","label":"Grade 5","where":{"year":{"eq":6,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-6","label":"Grade 6","where":{"year":{"eq":7,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-7","label":"Grade 7","where":{"year":{"eq":8,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-8","label":"Grade 8","where":{"year":{"eq":9,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-9","label":"Grade 9","where":{"year":{"eq":10,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-10","label":"Grade 10","where":{"year":{"eq":11,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-11","label":"Grade 11","where":{"year":{"eq":12,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-12","label":"Grade 12","where":{"year":{"eq":13,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}}]}'::jsonb, 'DE-SN', 'VwV Stundentafeln vom 20.6.2018 (MBl. SMK S. 347), Fassung gueltig 2026-08-01 bis 2027-07-31, https://www.revosax.sachsen.de/vorschrift/17744.7. Weekly hours read directly from the official PDF on 2026-10-25.', 'proposed', 'computer-science') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('592910ec-c1dd-52ba-a209-9642e897ba17', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, 'b83f2e8b-a036-517f-934e-2ac89f1872d9', NULL, 'Technik/Computer (grades 5 and 6) and Informatik (grades 7 to 10) have 1 weekly lesson hour each year in grades 5 to 10 (Anlage 4a). Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25. Counting Technik/Computer and Informatik as one host is a modelling choice.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
