INSERT INTO lpm_time_plans (id, project_id, axis_id, name, summary, kind, parameters, status)
VALUES ('c4451683-6fd1-5f2b-a89e-e187bfeadb1d', '371fce26-d1f3-439b-95df-0a0e38b8a824', '92f90164-7b91-5200-85bb-43b82ec5a237', 'Sachsen hours: short blocks that return each year, plus a small thread', 'The same pattern as the matching starter plan, laid on the real Sachsen timetable. Grades 1 to 4 are taught inside Sachunterricht and grades 5 to 10 in the subjects of the Gymnasium. Each subject gives the same share of its own hours. The share is a placeholder, the hours are sourced, and the plan makes no recommendation.', 'planned', '{"preset":"spiral","share":{"low":0.1,"high":0.3},"reinforcing_share":0.15,"returns_per_year":2,"thread_fraction":0.25,"hosts":{"basis":"home-share","split":{"04d57493-ac2f-5ec6-a1ba-0596eae3158a":{"sachunterricht":1},"31b2be29-7a8c-5f98-a447-55ecf57f1ff9":{"sachunterricht":0.6666666666666666,"biology":0.16666666666666666,"social-studies":0.16666666666666666},"396e3dd9-4f22-5160-b6c7-3752caefa1b8":{"biology":0.5,"social-studies":0.5},"3a112595-4435-5db0-950d-ca7c6da5160d":{"biology":0.5,"social-studies":0.5},"5d938d91-e81b-516c-ba58-a234b6d5559f":{"biology":0.5,"social-studies":0.5},"6315aad7-35b7-52dc-9dd2-1b82d707a768":{"biology":0.5,"social-studies":0.5},"6f04ee30-2be3-537b-9d0e-b339d9fed79c":{"sachunterricht":1},"8363df74-ecd8-54e9-82f1-e93623f9995c":{"sachunterricht":1},"9fc65a59-5de1-51ad-ad30-a9c0faca177a":{"sachunterricht":1},"a1bc92d8-3730-53b8-a059-f3999e4387cf":{"sachunterricht":0.6666666666666666,"social-studies":0.16666666666666666,"computer-science":0.16666666666666666},"a64224d1-ac36-5b1c-b475-3c5af3aa4656":{"sachunterricht":0.6666666666666666,"biology":0.16666666666666666,"social-studies":0.16666666666666666},"ad0173a4-5c64-5d05-96ac-2b61810c4153":{"social-studies":0.5,"computer-science":0.5},"ba60a3be-0135-5b53-b88f-a7aecfe0ed96":{"biology":0.5,"social-studies":0.5},"d2dc3119-7af8-55d8-8bfe-b63a4ec56acb":{"biology":0.5,"social-studies":0.5},"db1fca08-0dcf-5910-a3df-2de902e8630a":{"sachunterricht":0.6666666666666666,"bi