INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('44e34437-e99f-55c3-b65e-87b04ab907f2', '7f604bf5-2f90-5f00-9160-30e9265971c4', NULL, 'b53cb573-35f0-5bdc-bc6a-6940157d161c', NULL, 'Biologie at the Gymnasium has 2, 2, 1, 1, 2 and 2 weekly lesson hours in grades 5 to 10 (Anlage 4a). Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, jurisdiction, source, status, subject)
VALUES ('1c3fd897-91c9-5e6a-9773-a40327ea0be4', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'Social studies group: Sachsen Gymnasium 2026/27', 'Social studies lesson hours of the Sachsen school year 2026/27, one unit per year from kindergarten (year 1) to grade 12 (year 13). Years outside the school type of this subject have no hours. Available time is a range from 25 weeks to 39 weeks.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"kindergarten","label":"Kindergarten","where":{"year":{"eq":1,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-1","label":"Grade 1","where":{"year":{"eq":2,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-2","label":"Grade 2","where":{"year":{"eq":3,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-3","label":"Grade 3","where":{"year":{"eq":4,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-4","label":"Grade 4","where":{"year":{"eq":5,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-5","label":"Grade 5","where":{"year":{"eq":6,"absolute":true}},"duration":{"low":"PT5625M","high":"PT8775M"},"note":"5 weekly lesson hours."},{"key":"grade-6","label":"Grade 6","where":{"year":{"eq":7,"absolute":true}},"duration":{"low":"PT6750M","high":"PT10530M"},"note":"6 weekly lesson hours."},{"key":"grade-7","label":"Grade 7","where":{"year":{"eq":8,"absolute":true}},"duration":{"low":"PT7875M","high":"PT12285M"},"note":"7 weekly lesson hours."},{"key":"grade-8","label":"Grade 8","where":{"year":{"eq":9,"absolute":true}},"duration":{"low":"PT6750M","high":"PT10530M"},"note":"6 weekly lesson hours."},{"key":"grade-9","label":"Grade 9","where":{"year":{"eq":10,"absolute":true}},"duration":{"low":"PT7875M","high":"PT12285M"},"note":"7 weekly lesson hours."},{"key":"grade-10","label":"Grade 10","where":{"year":{"eq":11,"absolute":true}},"duration":{"low":"PT9000M","high":"PT14040M"},"note":"8 weekly lesson hours."},{"key":"grade-11","label":"Grade 11","where":{"year":{"eq":12,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-12","label":"Grade 12","where":{"year":{"eq":13,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}}]}'::jsonb, 'DE-SN', 'VwV Stundentafeln vom 20.6.2018 (MBl. SMK S. 347), Fassung gueltig 2026-08-01 bis 2027-07-31, https://www.revosax.sachsen.de/vorschrift/17744.7. Weekly hours read directly from the official PDF on 2026-10-25.', 'proposed', 'social-studies') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('9df078f7-0ffe-599f-8fde-9f6763303edf', '7f604bf5-2f90-5f00-9160-30e9265971c4', NULL, '1c3fd897-91c9-5e6a-9773-a40327ea0be4', NULL, 'The social group adds Gemeinschaftskunde/Rechtserziehung/Wirtschaft, Geschichte, Geographie and Ethik: 5, 6, 7, 6, 7 and 8 weekly lesson hours in grades 5 to 10 (Anlage 4a). Students take Ethik or Religion, and the model counts that slot as Ethik. Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25. The grouping of four subjects into one host is a modelling choice.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, jurisdiction, source, status, subject)
VALUES ('5ad7ad16-f11c-5e90-a240-d00115248173', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'Computing: Sachsen Gymnasium 2026/27', 'Computer science lesson hours of the Sachsen school year 2026/27, one unit per year from kindergarten (year 1) to grade 12 (year 13). Years outside the school type of this subject have no hours. Available time is a range from 25 weeks to 39 weeks.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"kindergarten","label":"Kindergarten","where":{"year":{"eq":1,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-1","label":"Grade 1","where":{"year":{"eq":2,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-2","label":"Grade 2","where":{"year":{"eq":3,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-3","label":"Grade 3","where":{"year":{"eq":4,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-4","label":"Grade 4","where":{"year":{"eq":5,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-5","label":"Grade 5","where":{"year":{"eq":6,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-6","label":"Grade 6","where":{"year":{"eq":7,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-7","label":"Grade 7","where":{"year":{"eq":8,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-8","label":"Grade 8","where":{"year":{"eq":9,"absolute":true}},"duration":{"low":"PT1125M","high":"PT1755M"},"note":"1 weekly lesson hours."},{"key":"grade-9","label":"Grade 9","where":{"year":{"eq":1