INSERT INTO lpm_time_plans (id, project_id, axis_id, name, summary, kind, parameters, status)
VALUES ('930eea8e-632b-5476-8e07-8fe94f6225b4', '7f604bf5-2f90-5f00-9160-30e9265971c4', '1c3fd897-91c9-5e6a-9773-a40327ea0be4', 'Sachsen hours: short blocks that return each year, plus a small thread', 'The same pattern as the matching starter plan, laid on the real Sachsen timetable. Grades 1 to 4 are taught inside Sachunterricht and grades 5 to 10 in the subjects of the Gymnasium. Each subject gives the same share of its own hours. The share is a placeholder, the hours are sourced, and the plan makes no recommendation.', 'planned', '{"preset":"spiral","share":{"low":0.1,"high":0.3},"reinforcing_share":0.15,"returns_per_year":2,"thread_fraction":0.25,"hosts":{"basis":"home-share","split":{"2de4fac1-1590-5260-a501-d040c57c2acf":{"social-studies":1},"3d964122-338c-548e-882b-d833d2ec4209":{"sachunterricht":0.6666666666666666,"social-studies":0.3333333333333333},"504c7645-bc71-5a81-a114-cd2d598d1621":{"social-studies":1},"56eb4828-57c2-589b-92ba-180f901b2443":{"social-studies":1},"9ef944f3-b11a-5327-9082-b53ba736a834":{"social-studies":1},"aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c":{"sachunterricht":0.6666666666666666,"social-studies":0.3333333333333333},"c4836b7e-c2ac-5eda-9368-08e410453278":{"sachunterricht":1},"e0e725b5-1716-5f38-95d7-bdaa1297f892":{"social-studies":1},"ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85":{"sachunterricht":1},"f21b382b-ed4a-5e4e-b69b-d603834fbbe9":{"sachunterricht":0.6666666666666666,"social-studies":0.3333333333333333},"f7608bc0-18ff-52e5-8238-ac0220214ec9":{"sachunterricht":1},"fd772a6a-0dd8-5410-96c5-79f75443183c":{"social-studies":1}}}}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
