INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('08090415-e4e8-59bc-bc41-9e28c04cdddb', '7f604bf5-2f90-5f00-9160-30e9265971c4', '6e25257c-73b7-56e7-9dec-22958cee7a44', NULL, NULL, 'Every subject a space draws on gives the same share of its own hours (a share between 10 and 30 percent).', 'placeholder', 'low', 'No source.', 'The share is unknown. The same range is used for all four spaces. With real hours the absolute time a space takes differs by subject, because the subjects have different hours.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('03815561-e8fa-5a1b-9648-751f7b45342e', '7f604bf5-2f90-5f00-9160-30e9265971c4', '6e25257c-73b7-56e7-9dec-22958cee7a44', NULL, NULL, 'Grades 1 to 4 are taught inside Sachunterricht for every space, including the three disciplinary spaces.', 'literature', 'high', 'VwV Stundentafeln, Anlage 1a (read directly 2026-10-25).', 'The Grundschule has no lessons of biology, social studies or computing of its own. Sachunterricht is one integrated subject.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('c4838e97-cd2f-5f31-beba-84ae068f7c93', '7f604bf5-2f90-5f00-9160-30e9265971c4', '6e25257c-73b7-56e7-9dec-22958cee7a44', NULL, NULL, 'In the grade band 3-5, two thirds of a stage sits in Sachunterricht (grades 3 and 4) and one third in the subject of grade 5.', 'derived', 'medium', 'Counted from the grade bands of the axis.', 'The band holds three school years. A stage cannot be placed in one year, so the split follows the years.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('8b659be5-9212-53fb-9e3d-42ad12e2162b', '7f604bf5-2f90-5f00-9160-30e9265971c4', '6e25257c-73b7-56e7-9dec-22958cee7a44', NULL, NULL, 'Grades 11 and 12 (Kursstufe) are not modelled in this version.', 'derived', 'high', 'VwV Stundentafeln has no table for the Kursstufe. Rules are in SOGYA, transcribed by an agent and not re-read.', 'Courses are chosen individually and the Grundkurs and Leistungskurs hours differ. The stages of the 9-12 band are placed in grades 9 and 10 only, so they carry less time than their band would suggest.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('0b71111f-c6ce-5053-8200-c29789dfe685', '7f604bf5-2f90-5f00-9160-30e9265971c4', '930eea8e-632b-5476-8e07-8fe94f6225b4', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the space''s time as a thread.', 'placeholder', 'low', 'No source.', 'That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('94c3612e-6aff-5666-950a-51e22a96d0a5', '7f604bf5-2f90-5f00-9160-30e9265971c4', '8e2142e9-be28-5f14-8dd6-b3612c1f7825', NULL, NULL, 'Inside a band, each stage takes its own stretch of the band''s teaching time, in dependency order.', 'derived', 'low', 'Design note 2026-10-25, section 5.11.', 'The links come from this space''s own prerequisite claims. This is a rule of the model and makes no claim about how any school should sequence.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('f14522b7-4ac1-5d45-b783-fb180fbbd4da', '7f604bf5-2f90-5f00-9160-30e9265971c4', '2cf1a059-560e-5f99-99fa-aab8c81a7735', NULL, NULL, 'This plan reverses the dependency order on purpose. It is a negative control for the order check and carries no design intent.', 'derived', 'high', 'Design note 2026-10-25, section 5.11.', 'A check that never reports a violation tells us little.', NULL) ON CONFLICT (id) DO NOTHING;

-- computational-core-lpm-synth: 12 stages, 16 ordering claims, home subject computer-science
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, jurisdiction, source, status, subject)
VALUES ('e5ffb763-50e3-53ef-8124-8f292a20268d', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'Sachunterricht: Sachsen Grundschule 2026/27', 'Sachunterricht lesson hours of the Sachsen school year 2026/27, one unit per year from kindergarten (year 1) to grade 12 (year 13). Years outside the school type of this subject have no hours. Available time is a range from 25 weeks to 39 weeks.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"kindergarten","label":"Kindergarten","where":{"year":{"eq":1,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-1","label":"Grade 1","where":{"year":{"eq":2,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-2","label":"Grade 2","where":{"year":{"eq":3,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-3","label":"Grade 3","where":{"year":{"eq":4,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-4","label":"Grade 4","where":{"year":{"eq":5,"absolute":true}},"duration":{"low":"PT3375M","high":"PT5265M"},"note":"3 weekly lesson hours."},{"key":"grade-5","label":"Grade 5","where":{"year":{"eq":6,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-6","label":"Grade 6","where":{"year":{"eq":7,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-7","label":"Grade 7","where":{"year":{"eq":8,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-8","label":"Grade 8","where":{"year":{"eq":9,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-9","label":"Grade 9","where":{"year":{"eq":10,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-10","label":"Grade 10","where":{"year":{"eq":11,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-11","label":"Grade 11","where":{"year":{"eq":12,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}},{"key":"grade-12","label":"Grade 12","where":{"year":{"eq":13,"absolute":true}},"duration":{"low":"PT0M","high":"PT0M"}}]}'::jsonb, 'DE-SN', 'VwV Stundentafeln vom 20.6.2018 (MBl. SMK S. 347), Fassung gueltig 2026-08-01 bis 2027-07-31, https://www.revosax.sachsen.de/vorschrift/17744.7. Weekly hours read directly from the official PDF on 2026-10-25.', 'proposed', 'sachunterricht') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('b2d3cc46-509c-5a0a-8a45-01abfa0001fa', 'bac697ab-febe-5111-a5bd-f266b8b2d837', NULL, 'e5ffb763-50e3-53ef-8124-8f292a20268d', NULL, 'Sachunterricht has 3 weekly lesson hours in each of grades 1 to 4 (Grundschule, Anlage 1a). It is one integrated subject. Biologie, Chemie, Physik, Informatik, Geschichte, Geographie and Gemeinschaftskunde have no lessons of their own in grades 1 to 4.', 'literature', 'high', 'VwV Stundentafeln, Anlage 1a (https://revosax.sachsen.de/attachments/38081), read directly from the PDF 2026-10-25.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, jurisdiction, source, status, subject)
