VALUES ('2ab2231b-9571-5d9c-8702-45481daaf3d8', 'bac697ab-febe-5111-a5bd-f266b8b2d837', NULL, '42ad450e-ad14-5e1f-88a6-58056c8d7804', NULL, 'Biologie at the Gymnasium has 2, 2, 1, 1, 2 and 2 weekly lesson hours in grades 5 to 10 (Anlage 4a). Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
