INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('aff65d81-7097-5606-b7d1-61e07314cbdc', 'bac697ab-febe-5111-a5bd-f266b8b2d837', NULL, 'add97090-2fdc-54e9-95ea-1226135a1f3e', NULL, 'The social group adds Gemeinschaftskunde/Rechtserziehung/Wirtschaft, Geschichte, Geographie and Ethik: 5, 6, 7, 6, 7 and 8 weekly lesson hours in grades 5 to 10 (Anlage 4a). Students take Ethik or Religion, and the model counts that slot as Ethik. Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25. The grouping of four subjects into one host is a modelling choice.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
