VALUES ('79607111-da49-5c12-aaeb-7d42c7d1a710', 'bac697ab-febe-5111-a5bd-f266b8b2d837', NULL, 'a2400011-6ff8-5515-b48d-1cdb31cc3376', NULL, 'Technik/Computer (grades 5 and 6) and Informatik (grades 7 to 10) have 1 weekly lesson hour each year in grades 5 to 10 (Anlage 4a). Grades 11 and 12 are not modelled.', 'literature', 'high', 'VwV Stundentafeln, Anlage 4a (https://revosax.sachsen.de/attachments/35174), read directly from the PDF 2026-10-25. Counting Technik/Computer and Informatik as one host is a modelling choice.', 'The low end of the available time counts 25 weeks, which the Lehrpläne plan with. The high end counts 39 weeks, from a day count of the 2026/27 calendar that was not independently checked. A lesson hour is 45 minutes. The gap between the two ends is the time the Lehrplan leaves unassigned.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_plans (id, project_id, axis_id, name, summary, kind, parameters, status)
