INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('af7356b0-9ad7-55e7-9b14-42c769507206', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'fcdd9607-7f5d-578e-a571-2e25b98212a3', NULL, NULL, 'Every subject a space draws on gives the same share of its own hours (a share between 10 and 30 percent).', 'placeholder', 'low', 'No source.', 'The share is unknown. The same range is used for all four spaces. With real hours the absolute time a space takes differs by subject, because the subjects have different hours.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('869be65f-e259-51f5-a8ad-df0036d5644d', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'fcdd9607-7f5d-578e-a571-2e25b98212a3', NULL, NULL, 'Grades 1 to 4 are taught inside Sachunterricht for every space, including the three disciplinary spaces.', 'literature', 'high', 'VwV Stundentafeln, Anlage 1a (read directly 2026-10-25).', 'The Grundschule has no lessons of biology, social studies or computing of its own. Sachunterricht is one integrated subject.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('76af11ca-764a-5a5a-bc1d-f90372cdf1b3', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'fcdd9607-7f5d-578e-a571-2e25b98212a3', NULL, NULL, 'In the grade band 3-5, two thirds of a stage sits in Sachunterricht (grades 3 and 4) and one third in the subject of grade 5.', 'derived', 'medium', 'Counted from the grade bands of the axis.', 'The band holds three school years. A stage cannot be placed in one year, so the split follows the years.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('45ae1c4b-2071-5f18-9604-84e868681787', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'fcdd9607-7f5d-578e-a571-2e25b98212a3', NULL, NULL, 'Grades 11 and 12 (Kursstufe) are not modelled in this version.', 'derived', 'high', 'VwV Stundentafeln has no table for the Kursstufe. Rules are in SOGYA, transcribed by an agent and not re-read.', 'Courses are chosen individually and the Grundkurs and Leistungskurs hours differ. The stages of the 9-12 band are placed in grades 9 and 10 only, so they carry less time than their band would suggest.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('ecdedb8d-89f6-5883-8291-2b5a47ee39d6', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '8c1eb951-f9aa-5cb7-a72a-e8358b2d611d', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the space''s time as a thread.', 'placeholder', 'low', 'No source.', 'That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('edb65bf0-fae7-5713-9caf-2deb63b3cbcc', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'ddee29bc-09dd-565b-96de-a44f781616de', NULL, NULL, 'Inside a band, each stage takes its own stretch of the band''s teaching time, in dependency order.', 'derived', 'low', 'Design note 2026-10-25, section 5.11.', 'The links come from this space''s own prerequisite claims. This is a rule of the model and makes no claim about how any school should sequence.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('eb75d94c-0c1c-5500-8ed1-7a9b4f22d0b8', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '34a34516-8684-52ca-b7c4-00008b99fff5', NULL, NULL, 'This plan reverses the dependency order on purpose. It is a negative control for the order check and carries no design intent.', 'derived', 'high', 'Design note 2026-10-25, section 5.11.', 'A check that never reports a violation tells us little.', NULL) ON CONFLICT (id) DO NOTHING;

